Create Database SOMALI_BUSSINES


CREATE TABLE dbo.BusinessTransactions (
    Transaction_ID VARCHAR(20) NOT NULL PRIMARY KEY,
    [Date] DATE NOT NULL,
    Branch VARCHAR(50) NOT NULL,
    Department VARCHAR(50) NOT NULL,
    Category VARCHAR(50) NOT NULL,
    Description VARCHAR(100) NOT NULL,
    Revenue DECIMAL(12,2) NULL,
    Expense DECIMAL(12,2) NULL,
    Payment_Method VARCHAR(50) NOT NULL,
    Customer_Type VARCHAR(30) NOT NULL,
    Employee_ID VARCHAR(20) NOT NULL,
    Quantity DECIMAL(10,2) NULL,
    Unit_Price DECIMAL(12,2) NULL,
    Total_Amount DECIMAL(12,2) NULL,
    Status VARCHAR(20) NOT NULL
);
GO

GO

-- Example query
SELECT * FROM dbo.BusinessTransactions;

--Soo saar transactions-ka status-koodu yahay Paid

select *from dbo.BusinessTransactions
where status = 'Paid';

--Mogadishu oo keliya iyo transactions Paid ah

select * from dbo.BusinessTransactions
where Branch = 'mogadishu'
AND status =    'Paid';

--  Top 10 Transactions-ka ugu lacagta badan
select  Top 10 *from dbo.BusinessTransactions
ORDER BY Total_Amount desc

-- SUM REVENUE BY BRANCH

SELECT
    Branch,
    SUM(Revenue) AS Total_Revenue
FROM BusinessTransactions
GROUP BY Branch
ORDER BY Total_Revenue DESC;

--  CUSTOMER TYPE ANALYSIS
SELECT
    Customer_Type,
    COUNT(*) AS Total_Transactions,
    SUM(Revenue) AS Total_Revenue
FROM BusinessTransactions
GROUP BY Customer_Type
ORDER BY Total_Revenue DESC;

-- Payment_Method analyst

SELECT
    Payment_Method,
    COUNT(*) AS Total_Transactions,
    SUM(Total_Amount) AS Total_Sales
FROM BusinessTransactions
GROUP BY Payment_Method
ORDER BY Total_Sales DESC;

